steps.script:
$ErrorActionPreference='Stop'
$r=@{action='cloudflare_v2_private_deploy';state='starting';worker='ttactualidad-v2-private-test';v1_untouched=$true;other_workers_untouched=$true}
function RunSafe($exe,$arguments,$name) {
  $out=Join-Path $env:TEMP ('tt-v2-'+$name+'-stdout.txt')
  $err=Join-Path $env:TEMP ('tt-v2-'+$name+'-stderr.txt')
  $p=Start-Process -FilePath $exe -ArgumentList $arguments -WorkingDirectory (Get-Location).Path -Wait -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err
  if($p.ExitCode -ne 0) {throw ($name+'_EXIT_'+$p.ExitCode)}
  return ((Get-Content -Raw $out -ErrorAction SilentlyContinue) + [Environment]::NewLine + (Get-Content -Raw $err -ErrorAction SilentlyContinue))
}
try {
  $dir=Join-Path $env:TEMP 'ttactualidad-v2-private'
  if(!(Test-Path (Join-Path $dir '.git'))){throw 'MISSING_REPO'}
  Push-Location $dir
  try{
    $branch=(& git.exe branch --show-current)
    if($branch.Trim() -ne 'feature/ttactualidad-v2-private-worker-20261114'){throw 'WRONG_GIT_BRANCH'}
    $pull=RunSafe 'git.exe' @('pull','--ff-only','origin','feature/ttactualidad-v2-private-worker-20261114') 'git'
    $head=(& git.exe rev-parse HEAD).Trim()
    if($head -ne '47beb8fd58d84e585ccf923cfd578de3b6a1704d'){throw 'HEAD_MISMATCH'}
    Set-Location (Join-Path $dir 'v2\private-worker')
    $conf=Get-Content -LiteralPath '.\wrangler.jsonc' -Raw
    if(!$conf.Contains('"name": "ttactualidad-v2-private-test"')){throw 'WRONG_WORKER'}
    $build=RunSafe 'npm.cmd' @('run','build') 'build'
    if(!$build.Contains('TT_V2_PRIVATE_BUILD_READY=YES')){throw 'BUILD_FAILED'}
    $bundle=Get-Content -LiteralPath '.\dist\app.js' -Raw
    if(!$bundle.Contains('Radar · ') -or !$bundle.Contains('https://ttactualidad.rainyraven22.chatgpt.site/') -or !$bundle.Contains('/pilot/jordi-wild.webp')){throw 'BUNDLE_MISSING_FEATURES'}
    $deploy=RunSafe 'npx.cmd' @('wrangler','deploy','--keep-vars') 'deploy'
    if(!$deploy.Contains('Deployed ttactualidad-v2-private-test triggers')){throw 'DEPLOY_NOT_CONFIRMED'}
    $r.state='deployed';$r.git_sha=$head;$r.url='https://ttactualidad-v2-private-test.fabricelop.workers.dev'
  }finally{Pop-Location}
}catch{$r.state='failed';$r.reason=$_.Exception.Message}
Write-Output ('TTRESULT:'+($r|ConvertTo-Json -Compress))
